"use client";
import { TextArea } from "ui-lab-components/textarea";
import { Label } from "ui-lab-components/label";
export function MessageField({ onSubmit }: { onSubmit: () => void }) { return <div><Label htmlFor="message">Message</Label><TextArea id="message" onKeyDown={(event) => { if (event.key === "Enter" && (event.ctrlKey || event.metaKey)) { event.preventDefault(); onSubmit(); } }} /></div>; }
